pub fn is_sorted(arr: &Vec<i32>) -> bool {
    // Check all adjacent pairs; if any decreases, the whole array is not nondecreasing.
    // This implies the forall(i < j) condition by transitivity.
    arr.windows(2).all(|w| w[0] <= w[1])
}

